import pandas as pd
import numpy as np
import json
import sys

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # --- TOTALS ---
    rev_tw = df['Revenue_TW'].sum(skipna=True)
    rev_lw = df['Revenue_LW'].sum(skipna=True)
    rev_ly = df['Revenue_LY'].sum(skipna=True)
    units_tw = df['Units_TW'].sum(skipna=True)
    units_lw = df['Units_LW'].sum(skipna=True)
    orders_tw = df['Orders_TW'].sum(skipna=True)
    orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw),
        "formula": "sum(Revenue_LW)"
    })
    if not np.isnan(rev_ly) and rev_ly != 0:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(rev_ly),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw, 0),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw, 0),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw, 0),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw, 0),
        "formula": "sum(Orders_LW)"
    })

    if rev_lw and rev_lw != 0:
        wow_total = (rev_tw - rev_lw) / rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly and not np.isnan(rev_ly) and rev_ly != 0:
        yoy_total = (rev_tw - rev_ly) / rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # --- TOP ENTITIES BY REVENUE_TW (RANK) ---
    top_n = df.dropna(subset=['Revenue_TW']).sort_values('Rank').head(3)
    for _, row in top_n.iterrows():
        ent = row['Entity']
        facts.append({
            "entity": ent, "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW for entity"
        })
        if not pd.isna(row['Share_Pct']):
            facts.append({
                "entity": ent, "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Share_Pct for entity"
            })
        facts.append({
            "entity": ent, "metric": "rank", "period": "TW",
            "value": to_float(row['Rank'], 0),
            "formula": "Rank for entity"
        })

    # --- BIGGEST WoW MOVERS ---
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        gainer = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        loser = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": gainer['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(gainer['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (max)"
        })
        facts.append({
            "entity": loser['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(loser['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (min)"
        })

    # --- BIGGEST YoY MOVERS ---
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        gainer_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        loser_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": gainer_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(gainer_y['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (max)"
        })
        facts.append({
            "entity": loser_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(loser_y['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (min)"
        })

    # --- TOP UNITS / ORDERS ENTITY ---
    if df['Units_TW'].notna().any():
        top_units = df.loc[df['Units_TW'].idxmax()]
        facts.append({
            "entity": top_units['Entity'], "metric": "units", "period": "TW",
            "value": to_float(top_units['Units_TW'], 0),
            "formula": "max(Units_TW)"
        })

    if df['Orders_TW'].notna().any():
        top_orders = df.loc[df['Orders_TW'].idxmax()]
        facts.append({
            "entity": top_orders['Entity'], "metric": "orders", "period": "TW",
            "value": to_float(top_orders['Orders_TW'], 0),
            "formula": "max(Orders_TW)"
        })

    # Limit to 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
